// billing-frame.ts
import { connect, contract, createEndpoint, protocol } from '@migaia/rpc-core'
import { createWindowMessageTransport } from '@migaia/rpc-browser/adapters/window'

const transport = createWindowMessageTransport({
  target: window.parent,
  receiver: window,
  targetOrigin: 'https://shop.example' // 只接受来自、也只发往父页面这个源
})
const billing = await createEndpoint({
  id: 'billing-frame',
  transport,
  middlewares: [contract({ version: '1' }), protocol(), connect({ transport })]
})

billing.provide('calculateTotal', (context) => {
  const input = context.data as { prices: number[]; taxRate: number }
  const subtotal = input.prices.reduce((sum, price) => sum + price, 0)
  return context.success(subtotal * (1 + input.taxRate))
})

window.addEventListener('pagehide', () => void billing.dispose(), { once: true })

// parent.ts
import { connect, contract, createEndpoint, protocol } from '@migaia/rpc-core'
import { createWindowMessageTransport } from '@migaia/rpc-browser/adapters/window'

const iframe = document.querySelector<HTMLIFrameElement>('#billing')!
await new Promise<void>((resolve) => iframe.addEventListener('load', () => resolve(), { once: true }))

const transport = createWindowMessageTransport({
  target: iframe.contentWindow!,
  receiver: window,
  targetOrigin: new URL(iframe.src).origin
})
const billing = await createEndpoint({
  id: 'checkout-page',
  targetIds: ['billing-frame'],
  transport,
  middlewares: [contract({ version: '1' }), protocol(), connect({ transport })]
})

const total = await billing.send<number>('billing-frame', 'calculateTotal', {
  prices: [12, 30],
  taxRate: 0.08
})
console.log(total) // 45.36

await billing.dispose()

import { connect, createEndpoint } from '@migaia/rpc-core'
import { createBroadcastChannelTransport } from '@migaia/rpc-browser/adapters/broadcast-channel'

// 两个标签页（这里用同一进程里的两个 BroadcastChannel 实例模拟）共享频道名 'cart'。
const channelA = new BroadcastChannel('cart')
const channelB = new BroadcastChannel('cart')
const tabATransport = createBroadcastChannelTransport(channelA)
const tabBTransport = createBroadcastChannelTransport(channelB)

const tabB = await createEndpoint({
  id: 'tab-b',
  transport: tabBTransport,
  middlewares: [connect({ transport: tabBTransport })]
})
tabB.provide('cart.count', (context) => context.success(3))

const tabA = await createEndpoint({
  id: 'tab-a',
  targetIds: ['tab-b'],
  transport: tabATransport,
  middlewares: [connect({ transport: tabATransport })]
})
try {
  console.log(await tabA.send<number>('tab-b', 'cart.count', null)) // 3
} finally {
  await tabA.dispose()
  await tabB.dispose()
  // 适配器借用频道，不负责关闭；由创建它的一方关闭。
  channelA.close()
  channelB.close()
}

